from research_helpers import *
a=ev('https://www.sinovac.com/en-us/products/portfolio','Current manufacturer portfolio lists launched vaccine products; no assertion every product currently supplied in every country.')
b=ev('https://www.sinovac.com/en-us/portfolio/influenza','Manufacturer distinguishes Anflu, Panflu, Panflu.1 and TetrAnflu influenza vaccines.')
products=[]
for name,desc in [('Anflu','Inactivated split-virion influenza vaccine.'),('Panflu','Adjuvanted pandemic H5N1 influenza vaccine.'),('Panflu.1','Inactivated H1N1 influenza vaccine.'),('TetrAnflu','Quadrivalent inactivated influenza vaccine.')]:products.append(p(name,desc,b,'commercial',roles=['commercial_partner'],typ='product'))
for name,desc in [('Provarix','Live varicella vaccine.'),('Inlive','Inactivated enterovirus-71 vaccine.'),('Healive','Inactivated hepatitis A vaccine.'),('Bilive','Combined hepatitis A and B vaccine.'),('SINOVAC PPV23','23-valent pneumococcal polysaccharide vaccine.'),('SINOVAC Sabin-strain IPV','Inactivated poliomyelitis vaccine.'),('SINOVAC adsorbed tetanus vaccine','Adsorbed tetanus vaccine launched 2025.'),('CoronaVac','Inactivated SARS-CoV-2 vaccine.'),('SINOVAC live mumps vaccine','Live mumps vaccine.')]:products.append(p(name,desc,a,'commercial',roles=['commercial_partner'],typ='product'))
co=dict(company_id='cmp_1c5b41d9-5d03-4d37-a2cc-2e0ace3c68d6',products=products,evidence=[a,b],status='partial',coverage_note='Thirteen explicitly named marketed vaccine products recorded, including four distinct influenza products. Parent group commercial_partner role reflects subsidiary manufacture. Partial: named investigational/combination/mRNA/antibody candidates, discontinued SARS programme and jurisdiction-specific current availability need review. WHO listing or national launch not global approval; no generic vaccine category or influenza umbrella duplicate. Dose/package and seasonal strain updates grouped pending specific model/formulation evidence.')
(out/'batch-0270.json').write_text(json.dumps({'companies':[co]},indent=2));print(len(products))
